// src/services/vendor/reportEngine/headerBuilder.ts
// ============================================================================
// Joy PeopleHR — Enterprise Header & Executive Layout Engine
// Renders standard corporate header, KPI cards, empty banner, and sign-offs
// ============================================================================

import ExcelJS from 'exceljs';
import { SheetHeaderOptions, KpiCardItem } from './types';
import { COLORS, FONTS, BORDERS, ALIGN } from './excelStyles';

export class HeaderBuilder {
  /**
   * Renders the unified corporate brand header block (Rows 1 to 7)
   * Returns the next available row index.
   */
  static renderCorporateHeader(ws: ExcelJS.Worksheet, options: SheetHeaderOptions, maxCols = 15): number {
    const { config, sheetTitle } = options;
    const endColLetter = ws.getColumn(maxCols).letter;

    // Row 1: Primary Brand Banner
    ws.mergeCells(`A1:${endColLetter}1`);
    const row1Cell = ws.getCell('A1');
    const companyDisplayName = (config.company_name || 'JOY CORPORATE SOLUTIONS PVT LTD').toUpperCase();
    const siteDisplayName = (config.site_name || 'UNIT II').toUpperCase();
    row1Cell.value = `  ${companyDisplayName}   •   ${siteDisplayName}`;
    row1Cell.font = FONTS.TITLE_MAIN;
    row1Cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: COLORS.PRIMARY_DARK },
    };
    row1Cell.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(1).height = 32;

    // Row 2: Secondary Accent Bar
    ws.mergeCells(`A2:${endColLetter}2`);
    const row2Cell = ws.getCell('A2');
    row2Cell.value = `  Joy PeopleHR — Workforce Operations & Vendor Compliance Management`;
    row2Cell.font = { name: 'Segoe UI', size: 9, bold: true, color: { argb: 'FFE2E8F0' } };
    row2Cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: COLORS.PRIMARY_LIGHT },
    };
    row2Cell.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(2).height = 18;

    // Row 3: Blank separator
    ws.getRow(3).height = 8;

    // Rows 4 to 7: Metadata & Audit Matrix
    const midColIndex = Math.max(5, Math.floor(maxCols / 2));
    const leftEndCol = ws.getColumn(midColIndex).letter;
    const rightStartCol = ws.getColumn(midColIndex + 1).letter;

    // Row 4: Report Title (Left) + Status (Right)
    ws.mergeCells(`A4:${leftEndCol}4`);
    const titleCell = ws.getCell('A4');
    titleCell.value = sheetTitle.toUpperCase();
    titleCell.font = { name: 'Segoe UI', size: 12, bold: true, color: { argb: COLORS.PRIMARY_DARK } };
    titleCell.alignment = { vertical: 'middle', horizontal: 'left' };

    ws.mergeCells(`${rightStartCol}4:${endColLetter}4`);
    const statusCell = ws.getCell(`${rightStartCol}4`);
    const status = config.report_status || 'COMPANY VERIFIED';
    statusCell.value = `STATUS: [ ${status} ]`;
    statusCell.font = { name: 'Segoe UI', size: 9.5, bold: true, color: { argb: COLORS.PRIMARY_DARK } };
    statusCell.alignment = { vertical: 'middle', horizontal: 'right' };

    // Row 5: Period (Left) + Generated Date (Right)
    ws.mergeCells(`A5:${leftEndCol}5`);
    const periodCell = ws.getCell('A5');
    const periodStr = config.period_label || `${config.from_date} to ${config.to_date}`;
    periodCell.value = `Reporting Period: ${periodStr}`;
    periodCell.font = { name: 'Segoe UI', size: 9.5, bold: true, color: { argb: COLORS.TEXT_MAIN } };
    periodCell.alignment = { vertical: 'middle', horizontal: 'left' };

    ws.mergeCells(`${rightStartCol}5:${endColLetter}5`);
    const genCell = ws.getCell(`${rightStartCol}5`);
    genCell.value = `Generated: ${config.generated_at || new Date().toLocaleString('en-IN')}`;
    genCell.font = FONTS.DATA_MUTED;
    genCell.alignment = { vertical: 'middle', horizontal: 'right' };

    // Row 6: Vendor Name (Left) + Generated By (Right)
    ws.mergeCells(`A6:${leftEndCol}6`);
    const vendorCell = ws.getCell('A6');
    vendorCell.value = `Vendor: ${config.vendor_name || 'Joy Manpower Services Private Limited'}`;
    vendorCell.font = { name: 'Segoe UI', size: 9, bold: false, color: { argb: COLORS.TEXT_MAIN } };
    vendorCell.alignment = { vertical: 'middle', horizontal: 'left' };

    ws.mergeCells(`${rightStartCol}6:${endColLetter}6`);
    const byCell = ws.getCell(`${rightStartCol}6`);
    byCell.value = `Generated By: ${config.generated_by || 'HR Administrator'}`;
    byCell.font = FONTS.DATA_MUTED;
    byCell.alignment = { vertical: 'middle', horizontal: 'right' };

    // Row 7: Contract / PO (Left) + Template Version (Right)
    ws.mergeCells(`A7:${leftEndCol}7`);
    const contractCell = ws.getCell('A7');
    contractCell.value = `Contract / PO: ${config.contract_po || 'JOY-PO-2026-MP08'}   |   Site: ${config.site_name || 'Unit II'}`;
    contractCell.font = FONTS.DATA_MUTED;
    contractCell.alignment = { vertical: 'middle', horizontal: 'left' };

    ws.mergeCells(`${rightStartCol}7:${endColLetter}7`);
    const templateCell = ws.getCell(`${rightStartCol}7`);
    templateCell.value = `Template: ${config.template_version || 'v2.4 Enterprise Production'}   |   Security: Level 3 Audited`;
    templateCell.font = FONTS.DATA_MUTED;
    templateCell.alignment = { vertical: 'middle', horizontal: 'right' };

    // Add soft bottom border under header section
    for (let c = 1; c <= maxCols; c++) {
      const cell = ws.getCell(7, c);
      cell.border = {
        ...(cell.border || {}),
        bottom: { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } },
      };
    }

    // Row 8: Blank spacing
    ws.getRow(8).height = 10;

    return 9; // next row
  }

  /**
   * Renders horizontal executive KPI summary cards
   * Returns next row index after cards.
   */
  static renderKpiCards(ws: ExcelJS.Worksheet, startRow: number, kpis: KpiCardItem[], maxCols = 15): number {
    if (!kpis || kpis.length === 0) return startRow;

    const cardsCount = kpis.length;
    const colsPerCard = Math.max(1, Math.floor(maxCols / cardsCount));

    ws.getRow(startRow).height = 14;     // Label row
    ws.getRow(startRow + 1).height = 22; // Value row
    ws.getRow(startRow + 2).height = 10; // Spacing row

    kpis.forEach((kpi, idx) => {
      const startColIdx = idx * colsPerCard + 1;
      let endColIdx = (idx + 1) * colsPerCard;
      if (idx === cardsCount - 1) endColIdx = maxCols; // expand last card to full width

      const startColLetter = ws.getColumn(startColIdx).letter;
      const endColLetter = ws.getColumn(endColIdx).letter;

      // Label Cell
      ws.mergeCells(`${startColLetter}${startRow}:${endColLetter}${startRow}`);
      const labelCell = ws.getCell(`${startColLetter}${startRow}`);
      labelCell.value = kpi.label.toUpperCase();
      labelCell.font = FONTS.KPI_LABEL;
      labelCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: COLORS.FILL_CARD_BG } };
      labelCell.alignment = { horizontal: 'center', vertical: 'middle' };

      // Value Cell
      ws.mergeCells(`${startColLetter}${startRow + 1}:${endColLetter}${startRow + 1}`);
      const valCell = ws.getCell(`${startColLetter}${startRow + 1}`);
      valCell.value = kpi.value;
      valCell.font = FONTS.KPI_VAL;
      valCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: COLORS.FILL_CARD_BG } };
      valCell.alignment = { horizontal: 'center', vertical: 'middle' };

      // Apply border around the card
      for (let r = startRow; r <= startRow + 1; r++) {
        for (let c = startColIdx; c <= endColIdx; c++) {
          const cCell = ws.getCell(r, c);
          cCell.border = {
            top: r === startRow ? { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } } : undefined,
            bottom: r === startRow + 1 ? { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } } : undefined,
            left: c === startColIdx ? { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } } : undefined,
            right: c === endColIdx ? { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } } : undefined,
          };
        }
      }
    });

    return startRow + 3; // next row
  }

  /**
   * Renders a professional Empty State Banner when 0 records exist
   */
  static renderEmptyStateBanner(ws: ExcelJS.Worksheet, startRow: number, options: SheetHeaderOptions, maxCols = 15): number {
    const endColLetter = ws.getColumn(maxCols).letter;

    ws.mergeCells(`A${startRow}:${endColLetter}${startRow}`);
    const bannerTop = ws.getCell(`A${startRow}`);
    bannerTop.value = `  ℹ️  No records found for this reporting period.`;
    bannerTop.font = { name: 'Segoe UI', size: 10.5, bold: true, color: { argb: 'FF92400E' } };
    bannerTop.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: COLORS.FILL_EMPTY_BANNER } };
    bannerTop.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(startRow).height = 24;

    ws.mergeCells(`A${startRow + 1}:${endColLetter}${startRow + 1}`);
    const bannerSub = ws.getCell(`A${startRow + 1}`);
    const period = options.config.period_label || `${options.config.from_date} to ${options.config.to_date}`;
    bannerSub.value = `      Period: ${period}   |   Vendor: ${options.config.vendor_name}   |   Site: ${options.config.site_name}   |   Status: Zero Operational Activity Detected`;
    bannerSub.font = { name: 'Segoe UI', size: 8.5, color: { argb: 'FFB45309' } };
    bannerSub.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: COLORS.FILL_EMPTY_BANNER } };
    bannerSub.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    ws.getRow(startRow + 1).height = 18;

    // Border around banner
    for (let r = startRow; r <= startRow + 1; r++) {
      for (let c = 1; c <= maxCols; c++) {
        const cell = ws.getCell(r, c);
        cell.border = {
          top: r === startRow ? { style: 'thin', color: { argb: 'FFFCD34D' } } : undefined,
          bottom: r === startRow + 1 ? { style: 'thin', color: { argb: 'FFFCD34D' } } : undefined,
          left: c === 1 ? { style: 'thin', color: { argb: 'FFFCD34D' } } : undefined,
          right: c === maxCols ? { style: 'thin', color: { argb: 'FFFCD34D' } } : undefined,
        };
      }
    }

    ws.getRow(startRow + 2).height = 12; // separator
    return startRow + 3;
  }

  /**
   * Renders the executive approval & sign-off footer at the bottom of the worksheet
   */
  static renderApprovalSection(ws: ExcelJS.Worksheet, startRow: number, maxCols = 15): number {
    ws.getRow(startRow).height = 16; // blank line

    const signRow = startRow + 1;
    ws.getRow(signRow).height = 36;

    const endColLetter = ws.getColumn(maxCols).letter;
    ws.mergeCells(`A${signRow}:${endColLetter}${signRow}`);
    const cell = ws.getCell(`A${signRow}`);
    cell.value = `Prepared By: ___________________        Vendor Reviewed By: ___________________        Company HR Verified By: ___________________        Approved By: ___________________        Date: ___________________`;
    cell.font = FONTS.APPROVAL_TITLE;
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF8FAFC' } };
    cell.border = {
      top: { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } },
      bottom: { style: 'thin', color: { argb: COLORS.BORDER_MEDIUM } },
    };

    return signRow + 2;
  }
}
